// By manifest name; null when there is no such icon (a name from data, e.g. a command bar item).
inline const ui::IconData* find(const char* name) {
    for (const NamedIcon& n : kAll) {
        if (std::strcmp(n.name, name) == 0) return n.icon;
    }
    return nullptr;
}
